31	/**
32	 * Simple JavaBean domain object representing an owner.
33	 *
34	 * @author Ken Krebs
35	 * @author Juergen Hoeller
36	 * @author Sam Brannen
37	 * @author Michael Isvy
38	 */
39	@Entity
40	@Table(name = "owners")
41	public class Owner extends Person {
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "city")
47	    @NotEmpty
48	    private String city;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a '+' followed by 8 to 15 digits)")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    @Email
57	    private String email;
58	
59	    @Column(name = "registration_date")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "namesake_count")
66	    private Integer namesakeCount;
67	
68	    @Column(name = "bulk_signup_warning")
69	    private Boolean bulkSignupWarning;
70	
71	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
72	    private Set<Pet> pets;
73	
74	    public String getAddress() {
75	        return this.address;
76	    }
77	
78	    public void setAddress(String address) {
79	        this.address = normalizeAddress(address);
80	    }
81	
82	    public String getCity() {
83	        return this.city;
84	    }
85	
86	    public void setCity(String city) {
87	        this.city = city;
88	    }
89	
90	    public String getTelephone() {
91	        return this.telephone;
92	    }
93	
94	    public void setTelephone(String telephone) {
95	        this.telephone = telephone;
96	    }
97	
98	    public String getEmail() {
99	        return this.email;
100	    }
101	
102	    public void setEmail(String email) {
103	        this.email = normalizeEmail(email);
104	    }
105	
106	    public LocalDate getRegistrationDate() {
107	        return this.registrationDate;
108	    }
109	
110	    public void setRegistrationDate(LocalDate registrationDate) {
111	        this.registrationDate = registrationDate;
112	    }
113	
114	    public String getCustomerCode() {
115	        return this.customerCode;
116	    }
117	
118	    public void setCustomerCode(String customerCode) {
119	        this.customerCode = customerCode;
120	    }
121	
122	    public Integer getNamesakeCount() {
123	        return this.namesakeCount;
124	    }
125	
126	    public void setNamesakeCount(Integer namesakeCount) {
127	        this.namesakeCount = namesakeCount;
128	    }
129	
130	    public Boolean getBulkSignupWarning() {
131	        return this.bulkSignupWarning;
132	    }
133	
134	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
135	        this.bulkSignupWarning = bulkSignupWarning;
136	    }
137	
138	    /**
139	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
140	     * source of truth for how an email is persisted, so inputs that differ only in letter case
141	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
142	     * (create and update, mapper or hand-copied) stores the same canonical value.
143	     *
144	     * @param email the raw email, possibly {@code null}
145	     * @return the lower-cased form, or {@code null} if the input was {@code null}
146	     */
147	    public static String normalizeEmail(String email) {
148	        return email == null ? null : email.toLowerCase();
149	    }
150	
151	    /**
152	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
153	     * truth for how a telephone is compared and persisted, so inputs that differ only in
154	     * formatting (spaces, dashes, brackets) are treated as the same number.
155	     *
156	     * <p>The rules are:
157	     * <ul>
158	     *   <li>spaces, dashes and brackets are stripped;</li>
159	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
160	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
161	     *       is dropped from the national digits;</li>
162	     *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
163	     *   <li>for a recognized country code the national number (the digits after the country
164	     *       code) must have the length that code requires: {@code '+61'} requires 9 national
165	     *       digits and {@code '+1'} requires 10.</li>
166	     * </ul>
167	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
168	     * values are returned unchanged.
169	     *
170	     * @param telephone the raw telephone, possibly {@code null}
171	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
172	     *     valid E.164 number
173	     */
174	    public static String normalizeTelephone(String telephone) {
175	        if (telephone == null) {
176	            return null;
177	        }
178	        String trimmed = telephone.trim();
179	        boolean hasCountryCode = trimmed.startsWith("+");
180	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
181	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
182	        if (hasCountryCode) {
183	            stripped = stripped.substring(1);
184	        }
185	        if (!stripped.matches("\\d+")) {
186	            return null;
187	        }
188	        String digits;
189	        if (hasCountryCode) {
190	            digits = stripped;
191	        } else {
192	            if (stripped.startsWith("0")) {
193	                stripped = stripped.substring(1);
194	            }
195	            digits = "61" + stripped;
196	        }
197	        if (digits.length() < 8 || digits.length() > 15) {
198	            return null;
199	        }
200	        if (!hasValidNationalNumberLength(digits)) {
201	            return null;
202	        }
203	        return "+" + digits;
204	    }
205	
206	    /**
207	     * Required national-number length (the count of digits after the country code) for each
208	     * recognized country code, longest country code first so the prefix match is unambiguous.
209	     */
210	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
211	    static {
212	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
213	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
214	    }
215	
216	    /**
217	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
218	     * length its country code requires. A country code with no registered length places no
219	     * additional constraint and is accepted.
220	     *
221	     * @param digits the E.164 digits without the leading {@code '+'}
222	     * @return {@code true} if the national-number length is valid for the country code
223	     */
224	    private static boolean hasValidNationalNumberLength(String digits) {
225	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
226	            String countryCode = entry.getKey();
227	            if (digits.startsWith(countryCode)) {
228	                return digits.length() - countryCode.length() == entry.getValue();
229	            }
230	        }
231	        return true;
232	    }
233	
234	    /**
235	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
236	     * upper-cased abbreviation.
237	     */
238	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
239	        "ST", "STREET",
240	        "RD", "ROAD",
241	        "AVE", "AVENUE");
242	
243	    /**
244	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
245	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
246	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
247	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
248	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
249	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
250	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
251	     * value. The transform is idempotent: a normalized address normalizes to itself.
252	     *
253	     * @param address the raw address, possibly {@code null}
254	     * @return the normalized form, or {@code null} if the input was {@code null}
255	     */
256	    public static String normalizeAddress(String address) {
257	        if (address == null) {
258	            return null;
259	        }
260	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
261	        if (collapsed.isEmpty()) {
262	            return collapsed;
263	        }
264	        String[] tokens = collapsed.split(" ");
265	        StringBuilder normalized = new StringBuilder(collapsed.length());
266	        for (int i = 0; i < tokens.length; i++) {
267	            if (i > 0) {
268	                normalized.append(' ');
269	            }
270	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
271	        }
272	        return normalized.toString();
273	    }
274	
275	    /**
276	     * Normalize a household field (such as last name or address) to its canonical form for
277	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
278	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
279	     * that differ only in letter case or spacing are treated as the same value.
280	     *
281	     * @param value the raw field value, possibly {@code null}
282	     * @return the normalized form, or {@code null} if the input was {@code null}
283	     */
284	    public static String normalizeHousehold(String value) {
285	        if (value == null) {
286	            return null;
287	        }
288	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
289	    }
290	
291	    /**
292	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
293	     * last name (compared case-insensitively with collapsed whitespace, see
294	     * {@link #normalizeHousehold(String)}) and the same normalized address (see
295	     * {@link #normalizeAddress(String)}). The value is deterministic in those two fields, so two
296	     * owners who share a household are assigned the same id. It is formatted {@code 'HH-<HEX12>'}
297	     * where {@code HEX12} is the first twelve upper-cased hex characters of the SHA-256 digest of
298	     * the normalized last name and address.
299	     *
300	     * @param lastName the owner's last name, possibly {@code null}
301	     * @param address the owner's address, possibly {@code null}
302	     * @return the household id, or {@code null} if either field is {@code null}
303	     */
304	    public static String householdId(String lastName, String address) {
305	        String normalizedLastName = normalizeHousehold(lastName);
306	        String normalizedAddress = normalizeAddress(address);
307	        if (normalizedLastName == null || normalizedAddress == null) {
308	            return null;
309	        }
310	        String key = normalizedLastName + "\n" + normalizedAddress;
311	        try {
312	            byte[] digest = MessageDigest.getInstance("SHA-256")
313	                .digest(key.getBytes(StandardCharsets.UTF_8));
314	            StringBuilder hex = new StringBuilder(digest.length * 2);
315	            for (byte b : digest) {
316	                hex.append(String.format("%02x", b));
317	            }
318	            return "HH-" + hex.substring(0, 12).toUpperCase();
319	        } catch (NoSuchAlgorithmException e) {
320	            // SHA-256 is a standard algorithm required to be present on every JVM.
321	            throw new IllegalStateException("SHA-256 not available", e);
322	        }
323	    }
324	
325	    /**
326	     * Build an owner's {@code membershipNumber}, the stable membership identifier derived from the
327	     * owner's own persisted fields. It is formatted {@code '<customerCode>-M<YY>'} where {@code YY}
328	     * is the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}). The
329	     * value is deterministic in those two fields.
330	     *
331	     * @param customerCode the owner's customer code, possibly {@code null}
332	     * @param registrationDate the owner's registration date, possibly {@code null}
333	     * @return the membership number, or {@code null} if either field is {@code null}
334	     */
335	    public static String membershipNumber(String customerCode, LocalDate registrationDate) {
336	        if (customerCode == null || registrationDate == null) {
